function refreshVoices(){voicesCache=speechSynthesis?.getVoices?.()||[];const v=selectEnglishVoice();$('voiceStatus').textContent=v?`질문 음성: ${v.name} (${v.lang})`:'영어 음성 목록을 기다리는 중'}
function selectEnglishVoice(){return voicesCache.find(v=>v.lang==='en-US'&&/natural|neural|enhanced/i.test(v.name))||voicesCache.find(v=>v.lang==='en-US')||voicesCache.find(v=>/^en[-_]/i.test(v.lang))||null}
async function ensureVoice(){for(let i=0;i<15;i++){refreshVoices();const v=selectEnglishVoice();if(v)return v;await new Promise(r=>setTimeout(r,100))}return null}
async function speakText(text,isPassage=false){if(!('speechSynthesis'in window))return;return new Promise(async resolve=>{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=Number(state.settings.ttsRate)||.95;u.voice=await ensureVoice();u.onend=resolve;u.onerror=resolve;speechSynthesis.speak(u)})}
if('speechSynthesis'in window){speechSynthesis.onvoiceschanged=refreshVoices;refreshVoices()}
function revealQuestion(isReplay=false){const t=currentTasks[currentTaskIndex],shown=fullQuestion(t),seconds=effectiveRevealSec(t);questionSeen=true;if(isReplay)replayUsed=true;$('questionDisplay').className='question-text';$('questionDisplay').textContent=shown;$('revealBtn').disabled=true;$('replayBtn').classList.add('hidden');$('recordStart').disabled=true;if(state.settings.speakQuestion)speakText(shown.replace(/\n/g,' '),false);let left=seconds;$('countdown').textContent=`${left}초`;$('countdown').classList.remove('hidden');clearReveal();revealInterval=setInterval(()=>{left--;$('countdown').textContent=`${left}초`;if(left<=0){hideQuestion()}},1000)}
function hideQuestion(){clearReveal();speechSynthesis?.cancel?.();$('questionDisplay').className='question-hidden';$('questionDisplay').textContent='질문이 가려졌습니다. 답을 미리 쓰지 말고 녹음 시작을 누르세요.';$('countdown').classList.add('hidden');questionHiddenAt=performance.now();$('recordStart').disabled=false;if(!replayUsed)$('replayBtn').classList.remove('hidden')}
function clearReveal(){if(revealInterval){clearInterval(revealInterval);revealInterval=null}}
$('revealBtn').onclick=()=>revealQuestion(false);$('replayBtn').onclick=()=>revealQuestion(true);
function chooseMime(){if(!window.MediaRecorder)return null;const list=['audio/mp4;codecs=mp4a.40.2','audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus','audio/ogg'];for(const m of list){try{if(!MediaRecorder.isTypeSupported||MediaRecorder.isTypeSupported(m))return m}catch(e){}}return''}
async function prepareAnalyser(s){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return{startThreshold:.018,holdThreshold:.012,noiseMedian:null,noiseP75:null};audioContext=new AC();const source=audioContext.createMediaStreamSource(s);analyser=audioContext.createAnalyser();analyser.fftSize=2048;source.connect(analyser);const data=new Uint8Array(analyser.fftSize),samples=[];$('recordLabel').textContent='주변 소음 2초 측정 중… 잠시 조용히 기다려 주세요.';for(let i=0;i<40;i++){analyser.getByteTimeDomainData(data);samples.push(rms(data));await new Promise(r=>setTimeout(r,50))}const sorted=[...samples].sort((a,b)=>a-b),median=percentile(sorted,.5),p75=percentile(sorted,.75),deviations=sorted.map(x=>Math.abs(x-median)).sort((a,b)=>a-b),mad=percentile(deviations,.5);const adaptive=Math.max(p75*1.65,median+Math.max(.0055,mad*5));const startThreshold=Math.min(.09,Math.max(.012,adaptive));const holdThreshold=Math.max(.009,startThreshold*.68);return{startThreshold,holdThreshold,noiseMedian:median,noiseP75:p75}}
function percentile(sorted,p){if(!sorted.length)return 0;const idx=(sorted.length-1)*p,lo=Math.floor(idx),hi=Math.ceil(idx);return sorted[lo]+(sorted[hi]-sorted[lo])*(idx-lo)}
function rms(data){let sum=0;for(const x of data){const v=(x-128)/128;sum+=v*v}return Math.sqrt(sum/data.length)}
function startAnalysis(prep){if(!analyser)return;const data=new Uint8Array(analyser.fftSize);analysisState={startThreshold:prep.startThreshold,holdThreshold:prep.holdThreshold,noiseMedian:prep.noiseMedian,noiseP75:prep.noiseP75,firstSoundAt:null,soundCandidateAt:null,lowCandidateAt:null,inSpeech:false,silenceStart:null,longSilences:[],startedAt:performance.now()};analysisInterval=setInterval(()=>{analyser.getByteTimeDomainData(data);const now=performance.now(),level=rms(data),a=analysisState;if(!a.inSpeech){if(level>=a.startThreshold){if(a.soundCandidateAt==null)a.soundCandidateAt=now;if(now-a.soundCandidateAt>=200){const onset=a.soundCandidateAt;a.inSpeech=true;a.lowCandidateAt=null;if(a.firstSoundAt==null)a.firstSoundAt=onset;if(a.silenceStart!=null){const d=(onset-a.silenceStart)/1000;if(d>=3)a.longSilences.push(d);a.silenceStart=null}}}else a.soundCandidateAt=null}else{if(level<a.holdThreshold){if(a.lowCandidateAt==null)a.lowCandidateAt=now;if(now-a.lowCandidateAt>=300){a.inSpeech=false;a.silenceStart=a.lowCandidateAt;a.soundCandidateAt=null}}else a.lowCandidateAt=null}},50)}
function finalizeAnalysis(){if(!analysisState)return{speechOnset:null,longSilenceCount:0,longSilenceSeconds:0,noiseMedian:null,startThreshold:null};const now=performance.now();if(analysisState.silenceStart!=null){const d=(now-analysisState.silenceStart)/1000;if(d>=3)analysisState.longSilences.push(d)}return{speechOnset:analysisState.firstSoundAt==null?null:(analysisState.firstSoundAt-analysisState.startedAt)/1000,longSilenceCount:analysisState.longSilences.length,longSilenceSeconds:analysisState.longSilences.reduce((a,b)=>a+b,0),noiseMedian:analysisState.noiseMedian,startThreshold:analysisState.startThreshold}}
function stopLiveResources(){if(recordInterval){clearInterval(recordInterval);recordInterval=null}if(analysisInterval){clearInterval(analysisInterval);analysisInterval=null}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}if(audioContext){audioContext.close().catch(()=>{});audioContext=null}analyser=null;analysisState=null}
async function startRecording(){const t=currentTasks[currentTaskIndex];if(!window.isSecureContext&&location.protocol!=='localhost:')return showMicError({name:'SecurityError'});if(!navigator.mediaDevices?.getUserMedia)return showMicError({name:'UnsupportedError'});if(!window.MediaRecorder)return showMicError({name:'MediaRecorderUnsupported'});if(clipCache[recordingTarget]&&!confirm(`${recordingTarget==='first'?'1차 답변':'재도전'} 녹음을 덮어쓸까요?`))return;try{const clickAt=performance.now();$('recordLabel').textContent='마이크 준비 중…';stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const prep=await prepareAnalyser(stream);currentMime=chooseMime();currentExt=extForMime(currentMime);mediaRecorder=new MediaRecorder(stream,currentMime?{mimeType:currentMime}:undefined);const chunks=[];mediaRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};mediaRecorder.onerror=e=>showMicError(e.error||e);mediaRecorder.onstop=async()=>{const duration=(performance.now()-recordStartAt)/1000;const analysis=finalizeAnalysis();const blob=new Blob(chunks,{type:mediaRecorder.mimeType||currentMime||'audio/webm'});const metrics={buttonDelay:questionHiddenAt==null?null:(clickAt-questionHiddenAt)/1000,speechOnset:analysis.speechOnset,longSilenceCount:analysis.longSilenceCount,longSilenceSeconds:analysis.longSilenceSeconds,duration,noiseMedian:analysis.noiseMedian,startThreshold:analysis.startThreshold,mime:blob.type,createdAt:new Date().toISOString()};stopLiveResources();const key=`${t.id}:${recordingTarget}`;await dbPut({key,taskId:t.id,source:t.source,sessionId:currentSession.id,take:recordingTarget,title:t.title,blob,mime:blob.type,ext:extForMime(blob.type),metrics,createdAt:metrics.createdAt});const r=ensureRecord(t);r.takes=r.takes||{};r.takes[recordingTarget]=metrics;r.savedAt=new Date().toISOString();saveState();await loadTakes(t);$('recordLabel').textContent='녹음이 기기에 저장되었습니다.';$('recordStop').disabled=true;$('recordStart').disabled=false;$('nextTask').disabled=false;if(t.type==='listening'&&$('showPassage'))$('showPassage').classList.remove('hidden');renderStorageStats()};mediaRecorder.start(250);recordStartAt=performance.now();startAnalysis(prep);recordInterval=setInterval(()=>{$('recordTimer').textContent=fmt((performance.now()-recordStartAt)/1000)},250);$('recordLabel').innerHTML='<span class="pulse"></span>녹음 중';$('recordStart').disabled=true;$('recordStop').disabled=false;$('nextTask').disabled=true}catch(e){stopLiveResources();showMicError(e)}}
function stopRecording(){if(!mediaRecorder||mediaRecorder.state!=='recording')return;mediaRecorder.stop();if(recordInterval){clearInterval(recordInterval);recordInterval=null}$('recordLabel').textContent='녹음을 저장하는 중…';$('recordStop').disabled=true}
function showMicError(e){const name=e?.name||'UnknownError';const local=location.protocol==='file:'||location.protocol==='content:';let msg;if(local||name==='SecurityError')msg='<b>HTTPS 주소가 필요합니다.</b><br>다운로드 파일로 직접 열지 말고 GitHub Pages 주소로 접속하세요.';else if(name==='NotAllowedError'||name==='PermissionDeniedError')msg='<b>마이크 권한이 거부되었습니다.</b><br>주소창의 사이트 정보 → 권한 → 마이크 → 허용으로 바꾼 뒤 새로고침하세요.';else if(name==='NotFoundError'||name==='DevicesNotFoundError')msg='<b>사용 가능한 마이크를 찾지 못했습니다.</b><br>블루투스 기기 연결을 확인하거나 다른 입력 장치를 선택하세요.';else if(name==='NotReadableError'||name==='TrackStartError'||name==='AbortError')msg='<b>마이크를 열 수 없습니다.</b><br>통화·카메라·녹음 앱이 마이크를 사용 중인지 확인한 뒤 다시 시도하세요.';else if(name==='MediaRecorderUnsupported'||name==='UnsupportedError'||name==='NotSupportedError'||name==='TypeError')msg='<b>이 브라우저의 녹음 형식을 지원하지 않습니다.</b><br>iPhone은 최신 iOS Safari에서 다시 시도하고, Android는 최신 Chrome을 권장합니다.';else msg=`<b>녹음을 시작하지 못했습니다.</b><br>오류: ${esc(name)}. 브라우저를 최신 버전으로 업데이트한 뒤 다시 시도하세요.`;$('micHelp').classList.remove('hidden');$('micHelp').classList.add('errornotice');$('micHelp').innerHTML=msg;$('recordLabel').textContent='마이크를 시작하지 못했습니다.'}
$('recordStart').onclick=startRecording;$('recordStop').onclick=stopRecording;
function setTake(which){recordingTarget=which;$('takeFirst').classList.toggle('selected',which==='first');$('takeRetry').classList.toggle('selected',which==='retry');updateMetricPanel()}
$('takeFirst').onclick=()=>setTake('first');$('takeRetry').onclick=()=>setTake('retry');
function revokeClipUrls(){for(const k of ['first','retry']){if(clipUrls[k])URL.revokeObjectURL(clipUrls[k]);clipUrls[k]=null;clipCache[k]=null}}
async function loadTakes(t){revokeClipUrls();for(const take of ['first','retry']){const clip=await dbGet(`${t.id}:${take}`);clipCache[take]=clip||null;if(clip){clipUrls[take]=URL.createObjectURL(clip.blob)}}renderSavedTakes();updateMetricPanel()}
function metricText(m,key){if(!m)return'-';if(key==='buttonDelay'||key==='speechOnset')return m[key]==null?'-':`${m[key].toFixed(1)}초`;if(key==='silence')return`${m.longSilenceCount||0}회 / ${(m.longSilenceSeconds||0).toFixed(1)}초`;if(key==='duration')return fmt(m.duration);return'-'}
function currentMetrics(){return state.records[currentTasks[currentTaskIndex]?.id]?.takes?.[recordingTarget]||clipCache[recordingTarget]?.metrics||null}
function updateMetricPanel(){const m=currentMetrics(),wc=wordCount($('transcript').value),wpm=m?.duration&&wc?Math.round(wc/(m.duration/60)):null;$('metricDelay').textContent=metricText(m,'buttonDelay');$('metricOnset').textContent=metricText(m,'speechOnset');$('metricSilence').textContent=metricText(m,'silence');$('metricDuration').textContent=metricText(m,'duration');$('metricWpm').textContent=wpm?String(wpm):'-'}
function renderSavedTakes(){const root=$('savedTakes');const cards=[];for(const take of ['first','retry']){const c=clipCache[take];if(!c)continue;const label=take==='first'?'1차 답변':'재도전';cards.push(`<div class="take-card"><div class="take-head"><div><h4>${label}</h4><div class="take-meta">${new Date(c.createdAt).toLocaleString()} · ${esc(c.ext||extForMime(c.mime))}</div></div><div class="btnrow"><button class="btn secondary small" data-download="${take}">다운로드</button><button class="btn danger small" data-delete="${take}">삭제</button></div></div><audio controls src="${clipUrls[take]}"></audio><div class="take-meta">시작 지연 ${metricText(c.metrics,'buttonDelay')} · 소리 감지 시작(추정) ${metricText(c.metrics,'speechOnset')} · 낮은 음량 3초+(추정) ${metricText(c.metrics,'silence')} · 길이 ${metricText(c.metrics,'duration')}</div></div>`)}if(clipCache.first&&clipCache.retry){const a=clipCache.first.metrics,b=clipCache.retry.metrics;cards.push(`<table class="compare"><tr><th>비교</th><th>1차</th><th>재도전</th></tr><tr><td>버튼 시작 지연</td><td>${metricText(a,'buttonDelay')}</td><td>${metricText(b,'buttonDelay')}</td></tr><tr><td>소리 감지 시작(추정)</td><td>${metricText(a,'speechOnset')}</td><td>${metricText(b,'speechOnset')}</td></tr><tr><td>낮은 음량 3초+(추정)</td><td>${metricText(a,'silence')}</td><td>${metricText(b,'silence')}</td></tr><tr><td>답변 길이</td><td>${metricText(a,'duration')}</td><td>${metricText(b,'duration')}</td></tr></table>`)}root.innerHTML=cards.join('')||'<div class="listen-status">아직 저장된 녹음이 없습니다.</div>';root.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadTake(b.dataset.download));root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteTake(b.dataset.delete))}
function downloadTake(take){const c=clipCache[take];if(!c)return;const a=document.createElement('a');a.href=clipUrls[take];a.download=`${currentTasks[currentTaskIndex].id}_${take}.${c.ext||extForMime(c.mime)}`;a.click()}
async function deleteTake(take){if(!confirm(`${take==='first'?'1차 답변':'재도전'} 녹음을 삭제할까요?`))return;const t=currentTasks[currentTaskIndex];await dbDelete(`${t.id}:${take}`);const r=state.records[t.id];if(r?.takes)delete r.takes[take];saveState();await loadTakes(t);renderStorageStats()}
function collectChecks(){return Object.fromEntries([...document.querySelectorAll('#checks input')].map(x=>[x.dataset.key,x.checked]))}
function ensureRecord(t){return state.records[t.id]||(state.records[t.id]={id:t.id,sessionId:currentSession.id,week:currentSession.week,label:currentSession.label,title:t.title,type:taskTypeName(t),question:fullQuestion(t),source:t.source,takes:{},savedAt:new Date().toISOString()})}
function scheduleQuality(r){return['fail','partial','success'].includes(r.outcome)?r.outcome:'partial'}
function updateReviewSchedule(t,r){if(!r.outcome)return;const src=t.source,order=currentSession.order,attemptKey=`${currentSession.id}:${t.id}`;const old=state.reviewMeta[src]||{source:src,streak:0,attempts:0,lastOrder:0,nextDueOrder:order+1,needsReview:true};const quality=scheduleQuality(r),isNew=old.lastAttemptKey!==attemptKey,base=isNew?old.streak:(old.streakBeforeAttempt??old.streak);let streak=base,interval=1;const m=r.takes?.retry||r.takes?.first||{};if(quality==='fail'){streak=0;interval=1}else if(quality==='partial'){streak=base;interval=(r.retry||(r.rating&&r.rating<=2))?1:(r.replayUsed?2:3)}else{streak=base+1;interval=[0,3,7,14,21][Math.min(streak,4)];let factor=1;if(r.replayUsed)factor*=.75;if((m.longSilenceCount||0)>=3)factor*=.8;if(r.rating&&r.rating<=3)factor*=.85;interval=Math.max(2,Math.round(interval*factor))}state.reviewMeta[src]={...old,source:src,attempts:old.attempts+(isNew?1:0),streakBeforeAttempt:isNew?old.streak:old.streakBeforeAttempt,streak,lastOrder:order,nextDueOrder:order+interval,lastQuality:quality,needsReview:quality!=='success'||r.retry,lastAttemptKey:attemptKey,lastRating:r.rating||0,lastOutcome:r.outcome};if(quality==='success'&&!r.retry){for(const rec of Object.values(state.records))if(rec.source===src)rec.retry=false}}
function saveCurrent(show=true){if(!currentSession||!currentTasks.length)return false;if(!currentOutcome){if(show)alert('오늘의 수행 결과에서 실패·부분 성공·성공 중 하나를 선택해 주세요.');return false}const t=currentTasks[currentTaskIndex],r=ensureRecord(t);Object.assign(r,{sessionId:currentSession.id,week:currentSession.week,label:currentSession.label,title:t.title,type:taskTypeName(t),question:fullQuestion(t),source:t.source,transcript:$('transcript').value.trim(),checks:collectChecks(),rating:currentRating,outcome:currentOutcome,retry:$('retryFlag').checked,replayUsed,listenPlays,savedAt:new Date().toISOString()});updateReviewSchedule(t,r);saveState();renderTaskNav();updateWordMetrics();if(show)toast('텍스트·수치·복습 일정 저장 완료');return true}
$('saveTask').onclick=()=>saveCurrent(true);$('nextTask').onclick=async()=>{if(!saveCurrent(true))return;if(currentTaskIndex<currentTasks.length-1)await loadTask(currentTaskIndex+1);else finishSession()};
function finishSession(){stopPassage();stopLiveResources();$('taskCard').classList.add('hidden');$('sessionEnd').classList.remove('hidden');$('sessionProgress').style.width='100%';window.scrollTo({top:$('sessionEnd').offsetTop-20,behavior:'smooth'})}
$('restartSession').onclick=async()=>{$('sessionEnd').classList.add('hidden');$('taskCard').classList.remove('hidden');await loadTask(0)};$('completeSession').onclick=()=>{state.completed[currentSession.id]=true;state.sessionHistory[currentSession.id]=new Date().toISOString();saveState();setTab('course')};
document.querySelectorAll('#rating button').forEach(b=>b.onclick=()=>{currentRating=Number(b.dataset.rate);document.querySelectorAll('#rating button').forEach(x=>x.classList.toggle('selected',x===b))});
document.querySelectorAll('#outcome button').forEach(b=>b.onclick=()=>{currentOutcome=b.dataset.outcome;document.querySelectorAll('#outcome button').forEach(x=>x.classList.toggle('selected',x===b))});
function updateWordMetrics(){const wc=wordCount($('transcript').value);$('wordInfo').textContent=`영어 단어 ${wc}개 · 받아쓰기를 입력한 경우에만 선택한 녹음 길이를 기준으로 WPM을 계산합니다.`;updateMetricPanel()}
function metricSummary(r){const f=r.takes?.first||{},x=r.takes?.retry||{};return `1차: 시작 버튼 지연 ${f.buttonDelay==null?'-':f.buttonDelay.toFixed(1)+'초'}, 소리 감지 시작(추정) ${f.speechOnset==null?'-':f.speechOnset.toFixed(1)+'초'}, 낮은 음량 3초+(추정) ${f.longSilenceCount??'-'}회, 길이 ${f.duration?fmt(f.duration):'-'}\n재도전: 시작 버튼 지연 ${x.buttonDelay==null?'-':x.buttonDelay.toFixed(1)+'초'}, 소리 감지 시작(추정) ${x.speechOnset==null?'-':x.speechOnset.toFixed(1)+'초'}, 낮은 음량 3초+(추정) ${x.longSilenceCount??'-'}회, 길이 ${x.duration?fmt(x.duration):'-'}`}
function taskPromptText(t,r){const checks=checksDef.map(([k,l])=>`- ${l}: ${r.checks?.[k]?'예':'아니오'}`).join('\n');return `당신은 현대자동차 SPA 영어 말하기 시험을 준비하는 학습자의 코치입니다. 목표는 최근 약 40점에서 45점 이상으로 올리는 것입니다. 공식 점수를 단정하지 마세요.\n\n[문제 유형]\n${taskTypeName(t)}\n\n[현재 질문]\n${fullQuestion(t)}\n\n[학습자가 실제로 말한 답변]\n${r.transcript||'(아직 받아쓰지 않음 — 먼저 실제 답변을 붙여넣으라고 요청하세요.)'}\n\n[앱 자동 측정 · 추정치]\n${metricSummary(r)}\n- 질문 다시보기: ${r.replayUsed?'사용':'미사용'}\n- 듣기 재생: ${r.listenPlays||0}회\n\n[자가평가]\n${checks}\n- 수행 결과: ${r.outcome||'미선택'}
- 답변 체감: ${r.rating||'미선택'}/5\n- 다시 연습 필요: ${r.retry?'예':'아니오'}\n\n다음 순서로 피드백하세요.\n1. 현재 질문에 직접 답했는지 평가하고, 후속 질문이라면 앞선 자료·상황과의 연결도 확인\n2. 잘한 점 2가지\n3. 점수를 막는 핵심 문제를 최대 3개만 지적\n4. 음량 기반 자동 추정치는 참고자료로만 사용하고, 실제 음성을 들을 수 없다면 발음이나 침묵을 단정하지 말 것\n5. 학습자가 실제로 말한 생각과 사실은 유지하면서 더 쉽고 완전한 개선 답변 제시\n6. 통째로 외우지 않도록 재사용 가능한 표현 덩어리 3~5개 추출\n7. 같은 질문에 재도전하도록 요청\n8. 재답변이 오면 1차와 비교해 가장 중요한 변화만 평가하고 자연스러운 꼬리 질문 1개 제시`}
$('taskPromptBtn').onclick=()=>{if(!saveCurrent(true))return;const t=currentTasks[currentTaskIndex],r=state.records[t.id];$('taskPrompt').textContent=taskPromptText(t,r);$('taskPromptArea').classList.remove('hidden')};$('copyTaskPrompt').onclick=()=>copyText($('taskPrompt').textContent);
$('sessionPromptBtn').onclick=()=>{const items=currentTasks.map(t=>({t,r:state.records[t.id]})).filter(x=>x.r?.transcript||x.r?.takes?.first);let text=`당신은 현대자동차 SPA 영어 말하기 시험 코치입니다. 다음은 Week ${currentSession.week} ${currentSession.label} 기록입니다. 공식 점수를 단정하지 말고 40점대 학습자의 45점 이상 목표에 맞춰 분석하세요.\n\n`;if(!items.length)text+='저장된 답변이 없습니다.';else items.forEach((x,i)=>{text+=`[답변 ${i+1} · ${taskTypeName(x.t)}]\n질문: ${fullQuestion(x.t)}\n실제 답변: ${x.r.transcript||'(받아쓰기 없음)'}\n${metricSummary(x.r)}\n수행 결과 ${x.r.outcome||'-'}, 체감 ${x.r.rating||'-'}/5, 다시보기 ${x.r.replayUsed?'사용':'미사용'}, 재연습 ${x.r.retry?'필요':'불필요'}\n\n`});text+=`전체 답변을 종합해 다음을 제공하세요.\n1. 공통 강점 2가지\n2. 반복되는 병목 최대 4개\n3. 문장 완성, 질문 직접 답하기, 이유·예시, 유창성, 듣기 요약, 시각자료 설명 평가\n4. 자동 수치에서 보이는 1차→재도전 변화\n5. 다음 회차에서 연습할 표현 틀 5개\n6. 가장 약한 답변 2개의 쉬운 개선안\n7. 짧은 재도전 과제 3개`; $('sessionPrompt').textContent=text;$('sessionPromptArea').classList.remove('hidden')};$('copySessionPrompt').onclick=()=>copyText($('sessionPrompt').textContent);
function copyText(t){navigator.clipboard?.writeText(t).then(()=>toast('복사했습니다.')).catch(()=>{const ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast('복사했습니다.')})}
function toast(msg){const d=document.createElement('div');d.textContent=msg;d.style.cssText='position:fixed;left:50%;bottom:28px;transform:translateX(-50%);background:#101828;color:white;padding:10px 16px;border-radius:999px;z-index:9999;font-weight:800;font-size:13px;max-width:90%;text-align:center';document.body.appendChild(d);setTimeout(()=>d.remove(),1600)}
function renderRecords(){const root=$('recordList'),recs=Object.values(state.records).sort((a,b)=>(b.savedAt||'').localeCompare(a.savedAt||''));if(!recs.length){root.innerHTML='<div class="card empty">아직 저장된 답변이 없습니다.</div>';return}root.innerHTML=recs.map(r=>{const meta=state.reviewMeta[r.source];return `<div class="record-item"><div class="task-type">WEEK ${r.week} · ${esc(r.label)} · ${esc(r.type)}</div><h4>${esc(r.title)}</h4><p>${esc(r.question)}</p>${r.transcript?`<div class="transcript">${esc(r.transcript)}</div>`:'<p>받아쓰기 없음</p>'}<div class="chips"><span class="chip">결과 ${r.outcome==='success'?'성공':r.outcome==='partial'?'부분 성공':r.outcome==='fail'?'실패':'-'}</span><span class="chip">체감 ${r.rating||'-'}/5</span>${r.takes?.first?'<span class="chip">1차 녹음</span>':''}${r.takes?.retry?'<span class="chip">재도전 녹음</span>':''}${r.retry?'<span class="chip" style="color:var(--danger)">재연습 필요</span>':''}${meta?`<span class="chip">다음 복습 ${meta.nextDueOrder}회차</span>`:''}</div><div class="btnrow" style="margin-top:9px"><button class="btn secondary small" data-open="${r.sessionId}">회차 열기</button><button class="btn danger small" data-del="${r.id}">기록 삭제</button></div></div>`}).join('');root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openSession(b.dataset.open));root.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(confirm('텍스트 기록과 이 문제의 녹음을 모두 삭제할까요?')){delete state.records[b.dataset.del];await dbDelete(`${b.dataset.del}:first`);await dbDelete(`${b.dataset.del}:retry`);saveState();renderRecords();renderStorageStats()}})}
$('clearFilter').onclick=renderRecords;
function syncSettings(){$('revealSec').value=state.settings.revealSec;$('ttsRate').value=String(state.settings.ttsRate);$('speakQuestion').checked=state.settings.speakQuestion;updateTheme();refreshVoices()}
$('revealSec').onchange=e=>{state.settings.revealSec=Math.min(30,Math.max(5,Number(e.target.value)||10));saveState();syncSettings()};$('ttsRate').onchange=e=>{state.settings.ttsRate=Number(e.target.value);saveState()};$('speakQuestion').onchange=e=>{state.settings.speakQuestion=e.target.checked;saveState()};$('darkMode').onchange=e=>{state.settings.darkMode=e.target.checked;updateTheme();saveState()};
$('exportData').onclick=exportJSON;function exportJSON(){const payload={...state,exportedAt:new Date().toISOString(),note:'텍스트·복습 기록 백업입니다. 모든 녹음과 기록을 함께 보관하려면 전체 ZIP 백업을 사용하세요.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});downloadBlob(blob,'spa45_beta_records.json')}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}




async function sha256Hex(data){if(!crypto?.subtle)return null;const buf=data instanceof ArrayBuffer?data:data.buffer.slice(data.byteOffset,data.byteOffset+data.byteLength);const hash=await crypto.subtle.digest('SHA-256',buf);return[...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function safeAudioName(c){const ext=c.ext||extForMime(c.mime);return`audio/${c.taskId}_${c.take}.${ext}`.replace(/[^A-Za-z0-9_./-]/g,'_')}
async function exportAudioZip(){if(typeof JSZip==='undefined')return alert('ZIP 모듈을 불러오지 못했습니다. vendor/jszip.min.js 파일이 함께 업로드되었는지 확인하세요.');const clips=await dbAll();const zip=new JSZip(),manifest={format:'spa45-backup',version:1,createdAt:new Date().toISOString(),clipCount:clips.length,entries:[]};zip.file('records.json',JSON.stringify({...state,exportedAt:manifest.createdAt},null,2));for(const c of clips){const file=safeAudioName(c),data=new Uint8Array(await c.blob.arrayBuffer()),sha256=await sha256Hex(data);zip.file(file,data,{binary:true});manifest.entries.push({key:c.key,taskId:c.taskId,source:c.source,sessionId:c.sessionId,take:c.take,title:c.title,mime:c.mime,ext:c.ext||extForMime(c.mime),metrics:c.metrics,createdAt:c.createdAt,file,bytes:data.byteLength,sha256})}zip.file('manifest.json',JSON.stringify(manifest,null,2));$('exportAudio').disabled=true;$('exportAudio').textContent='ZIP 생성·검증 중…';try{const bytes=await zip.generateAsync({type:'uint8array',compression:'DEFLATE',compressionOptions:{level:6}});const check=await JSZip.loadAsync(bytes),parsed=JSON.parse(await check.file('manifest.json').async('text'));if(parsed.clipCount!==clips.length||!check.file('records.json'))throw new Error('manifest count mismatch');for(const e of parsed.entries){const f=check.file(e.file);if(!f)throw new Error(`missing ${e.file}`);const data=await f.async('uint8array');if(data.byteLength!==e.bytes)throw new Error(`size mismatch ${e.file}`);if(e.sha256){const digest=await sha256Hex(data);if(digest!==e.sha256)throw new Error(`hash mismatch ${e.file}`)}}downloadBlob(new Blob([bytes],{type:'application/zip'}),`spa45_full_backup_${new Date().toISOString().slice(0,10)}.zip`);toast(`ZIP 검증 완료 · 녹음 ${clips.length}개`)}catch(e){console.error(e);alert('ZIP 백업 검증에 실패했습니다. 다운로드하지 않았습니다.\n'+e.message)}finally{$('exportAudio').disabled=false;$('exportAudio').textContent='전체 ZIP 백업·검증'}}
async function importAudioZip(file){if(!file)return;if(typeof JSZip==='undefined')return alert('ZIP 모듈을 불러오지 못했습니다.');if(!confirm('ZIP의 기록과 녹음으로 현재 데이터를 교체할까요? 먼저 현재 ZIP 백업을 만들어 두세요.'))return;try{const zip=await JSZip.loadAsync(file),mf=zip.file('manifest.json'),rf=zip.file('records.json');if(!mf||!rf)throw new Error('manifest.json 또는 records.json이 없습니다.');const manifest=JSON.parse(await mf.async('text'));if(manifest.format!=='spa45-backup'||!Array.isArray(manifest.entries))throw new Error('지원하지 않는 백업 형식입니다.');const nextState=JSON.parse(await rf.async('text'));const restored=[];for(const e of manifest.entries){const f=zip.file(e.file);if(!f)throw new Error(`녹음 누락: ${e.file}`);const data=await f.async('uint8array');if(data.byteLength!==e.bytes)throw new Error(`크기 불일치: ${e.file}`);if(e.sha256){const digest=await sha256Hex(data);if(digest!==e.sha256)throw new Error(`무결성 불일치: ${e.file}`)}restored.push({...e,blob:new Blob([data],{type:e.mime||'application/octet-stream'})})}await dbClear();for(const c of restored)await dbPut({key:c.key,taskId:c.taskId,source:c.source,sessionId:c.sessionId,take:c.take,title:c.title,blob:c.blob,mime:c.mime,ext:c.ext,metrics:c.metrics,createdAt:c.createdAt});state={...clone(defaultState),...nextState,settings:{...defaultState.settings,...(nextState.settings||{})},records:nextState.records||{},reviewMeta:nextState.reviewMeta||{},completed:nextState.completed||{}};saveState();syncSettings();renderRecords();await renderStorageStats();toast(`ZIP 복원 완료 · 녹음 ${restored.length}개`)}catch(e){console.error(e);alert('ZIP 복원에 실패했습니다. 기존 데이터는 ZIP 검증이 끝나기 전에는 지우지 않습니다.\n'+e.message)}finally{$('importAudio').value=''}}
$('exportAudio').onclick=exportAudioZip;$('importAudio').onchange=e=>importAudioZip(e.target.files?.[0]);
async function updatePersistenceStatus(request=false){const status=$('storageStatus'),help=$('storageHelp'),btn=$('persistStorage');if(!navigator.storage?.persisted){status.textContent='미지원';status.className='status-warn';help.textContent='이 브라우저는 지속 저장 상태 확인을 지원하지 않습니다. 일반 로컬 저장으로 사용하고 ZIP 백업을 자주 만드세요.';if(btn)btn.disabled=true;return false}try{let persisted=await navigator.storage.persisted();if(!persisted&&request&&navigator.storage.persist)persisted=await navigator.storage.persist();if(persisted){status.textContent='보존 저장 승인됨';status.className='status-good';help.textContent='브라우저가 이 사이트의 저장소를 우선 보존하도록 승인했습니다. 사용자가 사이트 데이터를 직접 삭제하면 사라질 수 있으므로 ZIP 백업은 계속 권장합니다.';if(btn){btn.disabled=true;btn.textContent='보존 저장 승인됨'}return true}status.textContent='일반 저장 · 백업 권장';status.className='status-warn';help.textContent='IndexedDB에 저장되지만 브라우저 정리·기기 저장공간 부족·사이트 데이터 삭제 시 사라질 수 있습니다. 저장 보존을 요청하고 ZIP 백업을 만드세요.';if(btn){btn.disabled=false;btn.textContent=request?'승인되지 않음 · 다시 요청':'저장 보존 요청'}return false}catch(e){status.textContent='상태 확인 오류';status.className='status-bad';help.textContent='저장소 상태를 확인하지 못했습니다. ZIP 백업을 우선 사용하세요.';return false}}
$('persistStorage').onclick=()=>updatePersistenceStatus(true);
async function renderStorageStats(){if(!db)return;try{const clips=await dbAll(),size=clips.reduce((a,c)=>a+(c.blob?.size||0),0);$('storageClipCount').textContent=`${clips.length}개`;$('storageBytes').textContent=bytesText(size);$('audioCount').textContent=clips.length;await updatePersistenceStatus(false)}catch(e){$('storageStatus').textContent='저장 기능 오류';$('storageStatus').className='status-bad'}}
function syncResetButton(){$('resetData').disabled=!($('resetBackupCheck').checked&&$('resetPhrase').value.trim()==='전체 초기화')}
$('resetBackupCheck').onchange=syncResetButton;$('resetPhrase').oninput=syncResetButton;$('resetData').onclick=async()=>{if($('resetData').disabled)return;if(!confirm('정말로 모든 텍스트 기록과 녹음을 삭제할까요? 이 작업은 되돌릴 수 없습니다.'))return;localStorage.removeItem(STORE_KEY);await dbClear();state=clone(defaultState);saveState();syncSettings();$('resetPhrase').value='';$('resetBackupCheck').checked=false;syncResetButton();renderRecords();renderStorageStats();toast('전체 초기화가 완료되었습니다.')};
window.addEventListener('beforeunload',()=>{stopPassage();stopLiveResources();revokeClipUrls();speechSynthesis?.cancel?.()});


// ---- Mobile usability helpers -------------------------------------------------
const HERO_COLLAPSE_KEY = 'spa45_hero_collapsed';

function syncHeroCard() {
  const hero = $('heroCard');
  const toggle = $('heroToggle');
  if (!hero || !toggle) return;
  const collapsed = localStorage.getItem(HERO_COLLAPSE_KEY) === '1';
  hero.classList.toggle('collapsed', collapsed);
  toggle.textContent = collapsed ? '소개 펼치기' : '소개 접기';
  toggle.setAttribute('aria-expanded', String(!collapsed));
}

function toggleHeroCard() {
  const collapsed = localStorage.getItem(HERO_COLLAPSE_KEY) === '1';
  localStorage.setItem(HERO_COLLAPSE_KEY, collapsed ? '0' : '1');
  syncHeroCard();
}

function syncMobileActionBar() {
  const bar = $('mobileActionBar');
  if (!bar) return;
  const practiceActive = $('panel-practice')?.classList.contains('active');
  const taskVisible = practiceActive && currentTasks.length > 0 && !$('practiceArea')?.classList.contains('hidden') && !$('taskCard')?.classList.contains('hidden');
  bar.classList.toggle('hidden', !taskVisible);
  if (!taskVisible) return;

  const task = currentTasks[currentTaskIndex];
  const step = `${currentTaskIndex + 1}/${currentTasks.length}`;
  $('mobileStep').textContent = step;
  $('mobileTaskName').textContent = task ? taskTypeName(task) : '훈련';
  if ($('mobileSessionProgress')) $('mobileSessionProgress').textContent = `${currentTaskIndex + 1} / ${currentTasks.length}`;

  const questionButton = $('mobileReveal');
  if (!questionSeen) {
    questionButton.textContent = '질문 보기';
    questionButton.disabled = $('revealBtn')?.disabled ?? true;
  } else if (!replayUsed && !$('replayBtn')?.classList.contains('hidden')) {
    questionButton.textContent = '1회 다시 보기';
    questionButton.disabled = $('replayBtn')?.disabled ?? false;
  } else {
    questionButton.textContent = '질문 확인 완료';
    questionButton.disabled = true;
  }

  const recording = mediaRecorder?.state === 'recording';
  const recordButton = $('mobileRecord');
  recordButton.textContent = recording ? '■ 녹음 종료' : '● 녹음 시작';
  recordButton.classList.toggle('danger', !recording);
  recordButton.classList.toggle('secondary', recording);
  recordButton.disabled = recording ? ($('recordStop')?.disabled ?? true) : ($('recordStart')?.disabled ?? true);

  $('mobileNext').disabled = !currentOutcome || recording;
}

$('heroToggle').onclick = toggleHeroCard;
$('mobileReveal').onclick = () => {
  if (!questionSeen) $('revealBtn')?.click();
  else if (!replayUsed && !$('replayBtn')?.classList.contains('hidden')) $('replayBtn')?.click();
};
$('mobileRecord').onclick = () => {
  if (mediaRecorder?.state === 'recording') $('recordStop')?.click();
  else $('recordStart')?.click();
};
$('mobileNext').onclick = () => $('nextTask')?.click();
window.addEventListener('resize', syncMobileActionBar);
setInterval(syncMobileActionBar, 250);

(async function boot(){syncHeroCard();renderCourse();syncSettings();renderChecks();if(typeof JSZip==='undefined')console.warn('JSZip missing');await initDB();await updateStats();syncMobileActionBar()})()
